mapper.sql:
select
  th.*,
  reference_name(reference_type_lk, reference_id) as reference_name,
  trs.last_read_message_id,
  (select count(*) from thread_messages where thread_id = th.thread_id and (trs.last_read_message_id is null or thread_message_id > trs.last_read_message_id)) as unread_count
from threads th
left join thread_read_status trs on trs.thread_id = th.thread_id and trs.user_id = #{userId}
where th.record_status_lk = 'AP'
and exists (
  SELECT * from vw_permissions vp where vp.current_user_id = #{userId} and vp.permission_lk = 'THREADS'
  and (
    vp.permission_target_lk = 'ALL'
    or (
      vp.permission_target_lk = 'OWN' and th.create_user_id = #{userId}
    ) or (
      vp.permission_target_lk = 'SUB' and vp.owner_user_id = th.create_user_id
    )
  )
)

mapper.select:

and (
  th.thread_id in (
    select thread_id from thread_messages where create_user_id = #{userId}
  ) or th.thread_id in (
    select thread_id
    from thread_message_tags tmt
    join thread_messages tm on tm.thread_message_id = tmt.thread_message_id
    where (
      (tmt.reference_type_lk = 'USER' and reference_id = #{userId})
      or (tmt.reference_type_lk = 'USER_GROUP' and reference_id in (select user_group_id from user_group_users where user_id = #{userId}))
    )
  )
)
